// The dimension is read from the content's field_values JSONB so any guide
// category can be tagged with the readiness dimension it addresses.
func (q *Queries) FindRoadmapContentByDimension(ctx context.Context, arg FindRoadmapContentByDimensionParams) ([]FindRoadmapContentByDimensionRow, error) {
	rows, err := q.db.Query(ctx, findRoadmapContentByDimension,
		arg.Dimension,
		arg.DestinationCountry,
		arg.JourneyStage,
		arg.VisaRoute,
		arg.OriginCountry,
		arg.Purpose,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []FindRoadmapContentByDimensionRow
	for rows.Next() {
		var i FindRoadmapContentByDimensionRow
		if err := rows.Scan(
			&i.Slug,
			&i.Title,
			&i.Description,
			&i.TargetCountry,
			&i.JourneyStage,
			&i.VisaRoute,
			&i.SourceCountry,
			&i.Purpose,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

